+const MAX_PORT = 65535;
+
+function parsePort(text: string, item: string): number {
+  if (!/^[0-9]+$/.test(text)) {
+    throw new Error(`Invalid port list item: "${item}"`);
+  }
+  const port = Number(text);
+  if (port < 1 || port > MAX_PORT) {
+    throw new Error(`Port out of range 1-${MAX_PORT}: "${item}"`);
+  }
+  return port;
+}
+
+function parseItem(item: string): PortRange {
+  const trimmed = item.trim();
+  if (trimmed === "") {
+    throw new Error("Empty item in port list");
+  }
+  const dash = trimmed.indexOf("-");
+  if (dash === -1) {
+    const port = parsePort(trimmed, trimmed);
+    return [port, port];
+  }
+  const from = parsePort(trimmed.slice(0, dash).trim(), trimmed);
+  const to = parsePort(trimmed.slice(dash + 1).trim(), trimmed);
+  if (to < from) {
+    throw new Error(`Range ends before it starts: "${trimmed}"`);
+  }
+  return [from, to];
+}

